#!/usr/bin/env python3
"""Write SPEC.md from results.json / preview_data.json / cutlist.csv (run after frame.py)."""
import csv, json, os
d = os.path.dirname(os.path.abspath(__file__))
P = json.load(open(os.path.join(d, "preview_data.json")))
S = P["summary"]
cut = {r[0]: r for r in list(csv.reader(open(os.path.join(d, "cutlist.csv"))))[1:]}
w = lambda n: "%s" % format(round(n), ",")

L = []
a = L.append
a("# Truss chassis prototype for a 349cc liquid-cooled single\n")
a("Minimal triangulated space frame, every joint a truss node. Engine is **not designed**: it is a placeholder box with mount nodes you move later. Generated by `frame.py` (all numbers below come from it).\n")
a("Axes: x forward, y left, z up, origin = swingarm pivot centre, millimetres.\n")
a("## 1. Targets and geometry\n")
a("| Item | Value |\n|---|---|")
for k, v in [("Wheelbase", "1400 mm (front axle x = 840, rear axle x = -560)"), ("Wheels", "17 in front and rear (R about 300 mm)"),
             ("Rake / trail", "25 deg / about 107 mm (fork offset 30 mm)"), ("Swingarm length", "560 mm"),
             ("Seat height", "800 mm above ground (neutral ergonomic, rider 170-180 cm)"),
             ("Hip point / footpeg / grips", "(-60, 540) / (300, 10) / (520, 680), side view x,z; hip to grips about 600 mm, hip to peg about 640 mm"),
             ("Engine envelope (placeholder)", "x 100..550, y -125..125, z -170..250 mm (450 x 250 x 420)"),
             ("Frame extent", "%s x %s x %s mm" % (w(S["extent_mm"]["x"][1] - S["extent_mm"]["x"][0]), w(S["extent_mm"]["y"][1] - S["extent_mm"]["y"][0]), w(S["extent_mm"]["z"][1] - S["extent_mm"]["z"][0])))]:
    a("| %s | %s |" % (k, v))
a("\nFor comparison, the Triumph Scrambler 900 is seat 790, wheelbase 1445, rake 25.6 deg, trail 109, 19/17 in wheels. This frame is a neutral naked-bike posture, not scrambler-style.\n")
a("## 2. Truss rules used\n")
a("- Straight tubes only. Member centrelines meet at one point at every node, so members carry axial load only.")
a("- Rank of the rigidity matrix is %d for %d nodes (3j - 6 = %d): **isostatic, %d members, none redundant**. Removing any member would make a mechanism." % (S["rigidity_rank"], S["nodes"], S["isostatic_count"], S["members"]))
a("- Seat (nodes C, S), tank (S, HT), footpegs (P), shock (M), swingarm pivot (D) and engine (E, F) all attach at nodes, never mid-span.")
a("- Engine mount cross tubes: E-E passes over the engine, F-F passes behind the engine. No tube enters the engine box (min gap %s mm, requirement 10 mm)." % S["min_gap_to_engine_mm"])
a("- The steering head tube (HT-HB, 50 x 3 mm) is the one non-truss element: it is a rigid link between two nodes.\n")
a("## 3. Nodes (mm)\n")
a("| Node | x | y | z | Role |\n|---|---|---|---|---|")
role = {"HT": "head tube top", "HB": "head tube bottom", "M": "shock top (centreline)", "C": "seat rear", "S": "seat front / tank", "D": "swingarm pivot", "E": "engine upper mount", "F": "engine lower-rear mount", "P": "footpeg"}
for n, p in P["nodes"].items():
    a("| %s | %s | %s | %s | %s |" % (n, w(p[0]), w(p[1]), w(p[2]), role.get(n[0] if n not in ("HT", "HB") else n, "")))
a("")
a("## 4. Members and results\n")
a("Tube sizes: **S** = 19 x 1.6 mm, **M** = 28 x 2 mm (pivot tube only), **H** = 50 x 3 mm head tube. Mild-steel ERW, yield taken as 250 MPa, E = 210 GPa. Forces in N, tension positive. SF = safety factor (target 2.0).\n")
a("| Member | Tube | Centreline mm | Cut mm | Static 1 g | Bump 3 g | Brake 1 g | SF yield | SF buckle |\n|---|---|---|---|---|---|---|---|---|")
for m in P["members"]:
    f = m["forces"]
    sb = "tension" if m["sf_buckle"] is None else "%.1f" % m["sf_buckle"]
    a("| %s | %s | %s | %s | %s | %s | %s | %.1f | %s |" % (m["id"], m["size"], w(m["len"]), w(float(cut[m["id"]][3])), w(f["static"]), w(f["bump_3g"]), w(f["brake_1g"]), m["sf_yield"], sb))
a("")
a("## 5. Load cases and method\n")
a("Pin-jointed 3D truss, stiffness method (numpy). Sprung mass %.0f kg: rider 90, engine 60, tank/fuel 20, misc 30, plus tube mass. Supports only remove rigid-body motion; reactions come out as %s N, which confirms each case is self-equilibrated.\n" % (S["cases"]["static"]["total_mass_kg"], "0.0"))
a("| Case | Front wheel N | Rear wheel N | Shock axial N | Max node movement mm |\n|---|---|---|---|---|")
for c, nm in (("static", "Static 1 g"), ("bump_3g", "Bump 3 g (vertical)"), ("brake_1g", "Braking 1 g")):
    a("| %s | %s | %s | %s | %.2f |" % (nm, w(S["cases"][c]["R_front_N"]), w(S["cases"][c]["R_rear_N"]), w(S["cases"][c]["shock_axial_N"]), S["u_max_mm"][c]))
a("\nFront wheel load enters the head bearings (HT, HB) through the fork. Rear wheel load enters through the shock (node M) and the swingarm pivot (D), from the swingarm moment balance (shock lower mount x = -300).\n")
a("Result: minimum yield safety factor **%.2f**, minimum buckling safety factor **%.2f**, no failing members." % (S["min_sf_yield"], S["min_sf_buckle"]))
a("Cornering is not a separate case: at 1 g lateral the bike leans about 45 deg and the frame sees roughly a 1.4 g vertical load, which the 3 g bump case covers for axial forces. Lateral kicks and torsion are not analysed.\n")
a("## 6. Fabrication (cheapest route)\n")
a("- Total tube: 19 x 1.6 mm %s mm, 28 x 2 mm %s mm, 50 x 3 mm head tube %s mm. Tube mass %.1f kg." % (w(S["tube_length_mm"]["S"]), w(S["tube_length_mm"]["M"]), w(S["tube_length_mm"]["H"]), S["tube_mass_kg"]))
a("- `cutlist.csv` lists each member's centreline length, the cut length (axis pierce to pierce) and the included angle and mating tube at each end. Cope (fishmouth) each end onto the mating tube, trim to fit.")
a("- Plates, 6 mm mild steel, flat patterns in `frame.dxf`: engine lug 70 x 90, hole 12 (x4); swingarm pivot plate 110 x 150, hole 20 (x2); footpeg plate 50 x 60, hole 10 (x2); shock plate 60 x 80, hole 12 (x1). A local laser or CNC shop is fine; JLCCNC can cut them too. JLCCNC is not a tube-frame service.")
a("- Order: tack the two head nodes and the pivot tube in a flat jig first, then build each side, then the cross tubes (D-D, E-E) and the M node, then weld out. Check diagonals and the node positions against `frame.step` before final welding.")
a("- Rough cost guess, not sourced: tube about 10 kg of steel, plates a few hundred rupees, welding and jig the main cost; plan roughly Rs 8,000 to 20,000 at a local workshop.\n")
a("## 7. Limits and what changes with the real engine\n")
a("- Idealised pin joints. Welded joints add some bending stiffness and some secondary bending; neither is modelled.")
a("- Lateral loads, torsion, fatigue, weld quality, chain/drive loads and crash loads are not analysed.")
a("- Engine mounts E, F and the envelope are placeholders. Edit `ENGINE`, nodes `E`, `F`, `P` in `frame.py` and rerun; the script re-checks rigidity, forces and clearance.")
a("- **This is not a certified motorcycle frame.** A frame that carries a rider needs real FEA and physical testing by a qualified person before anyone rides it.\n")
a("## 8. Files\n")
a("| File | Content |\n|---|---|")
for f, t in [("frame.py", "parametric generator, solver and exporter"), ("frame.step", "39 tubes, 9 plates and the engine box as named parts"), ("frame.dxf", "side, top, front wireframes and plate flat patterns (mm)"), ("cutlist.csv", "tube cut list"), ("preview.html / preview.template.html", "3D viewer (`build_preview.py` injects `preview_data.json`)"), ("results.json, preview_data.json", "solver output"), ("gen_spec.py", "writes this file")]:
    a("| `%s` | %s |" % (f, t))
a("\nRegenerate: `python frame.py && python build_preview.py && python gen_spec.py` (needs numpy, cadquery, ezdxf).")
open(os.path.join(d, "SPEC.md"), "w").write("\n".join(L) + "\n")
print("SPEC.md written", len(L), "lines")
